export const HIRES_VARIANTS = {
  lappland: ['classic','desolate'],
  texas:    ['classic','silent'],
  exusiai:  ['classic','covenant']
};

let ready = false;
export async function initHires(){
  if(ready) return;
  const load = async f => await (await fetch('/models/'+f+'.json')).json();
  const [lc, ld, base] = await Promise.all([
    load('lappland-classic'), load('lappland-desolate'), load('_shared-baseline')
  ]);
  iE = lc; aE = ld; PE = yD = dO = base;
  ready = true;
}
export function hiresReady(){ return ready; }

/** 与原作同名：$O(id, variant) -> { root, weapons, ... } */
export function buildHires(id, variant='classic'){
  if(!ready) throw new Error('initHires() 未完成');
  const vs = HIRES_VARIANTS[id];
  if(!vs) throw new Error('该角色无高模：'+id);
  const v = vs.includes(variant) ? variant : vs[0];
  return $O(id, v);
}
